<?php
declare(strict_types=1);

/**
 * checks.php — Lesson 1.1 acceptance checks
 * ==========================================
 *
 * THE SPECIFICATION. Read it before you write anything; it says precisely what
 * `Workshop\CourtesyVehicle` must do.
 *
 * DO NOT EDIT THIS FILE. It is run against your code by starter.php and against
 * the reference implementation by solution/run.php, and it must be the same
 * file in both cases or it is proving nothing.
 *
 * If you believe a check is wrong, that is worth pursuing — say so in the
 * Notes & Sticking Points table in PROGRESS.md rather than editing around it.
 */

use Workshop\CourtesyVehicle;

acceptance('Lesson 1.1 — Rich vs Anemic: CourtesyVehicle');


// ── It exists, in the right place, in the right shape ───────────────────────

check(
    'Workshop\CourtesyVehicle exists',
    static fn(): bool => class_exists(CourtesyVehicle::class)
);

check(
    'It is declared in domain/workshop/CourtesyVehicle.php',
    static fn(): bool => declared_in(CourtesyVehicle::class, 'domain/workshop/CourtesyVehicle.php')
);

check(
    'The class is final',
    static fn(): bool => (new ReflectionClass(CourtesyVehicle::class))->isFinal()
);


// ── Construction ────────────────────────────────────────────────────────────

check(
    'It can be constructed with a fleet code',
    static fn(): bool => succeeds(static fn() => new CourtesyVehicle('CV-01'))
);

check(
    'fleetCode() returns what it was constructed with',
    static fn(): bool => (new CourtesyVehicle('CV-01'))->fleetCode() === 'CV-01'
);

check(
    'An empty fleet code is refused with InvalidArgumentException',
    static fn(): bool => throws(InvalidArgumentException::class, static fn() => new CourtesyVehicle(''))
);

check(
    'A whitespace-only fleet code is refused with InvalidArgumentException',
    static fn(): bool => throws(InvalidArgumentException::class, static fn() => new CourtesyVehicle('   '))
);


// ── Allocation ──────────────────────────────────────────────────────────────

check(
    'A new courtesy vehicle is available',
    static fn(): bool => (new CourtesyVehicle('CV-01'))->isAvailable() === true
);

check(
    'A new courtesy vehicle is allocated to nothing',
    static fn(): bool => (new CourtesyVehicle('CV-01'))->allocatedToJobCard() === null
);

check(
    'After allocateTo(), it is no longer available',
    static function (): bool {
        $vehicle = new CourtesyVehicle('CV-01');
        $vehicle->allocateTo('JC-1001');
        return $vehicle->isAvailable() === false;
    }
);

check(
    'After allocateTo(), it reports the job card it is out on',
    static function (): bool {
        $vehicle = new CourtesyVehicle('CV-01');
        $vehicle->allocateTo('JC-1001');
        return $vehicle->allocatedToJobCard() === 'JC-1001';
    }
);

check(
    'Allocating an empty job card reference is refused with InvalidArgumentException',
    static fn(): bool => throws(
        InvalidArgumentException::class,
        static fn() => (new CourtesyVehicle('CV-01'))->allocateTo('')
    )
);

check(
    'RULE: allocating a vehicle that is already out is refused with DomainException',
    static fn(): bool => throws(
        DomainException::class,
        static function (): void {
            $vehicle = new CourtesyVehicle('CV-01');
            $vehicle->allocateTo('JC-1001');
            $vehicle->allocateTo('JC-1002');
        }
    )
);

check(
    'A refused second allocation leaves the original allocation intact',
    static function (): bool {
        $vehicle = new CourtesyVehicle('CV-01');
        $vehicle->allocateTo('JC-1001');
        try {
            $vehicle->allocateTo('JC-1002');
        } catch (DomainException) {
            // expected
        }
        return $vehicle->allocatedToJobCard() === 'JC-1001' && $vehicle->isAvailable() === false;
    }
);

check(
    'A refused allocation with an empty reference leaves the vehicle available',
    static function (): bool {
        $vehicle = new CourtesyVehicle('CV-01');
        try {
            $vehicle->allocateTo('');
        } catch (InvalidArgumentException) {
            // expected
        }
        return $vehicle->isAvailable() === true && $vehicle->allocatedToJobCard() === null;
    }
);


// ── Return ──────────────────────────────────────────────────────────────────

check(
    'After returnToFleet(), it is available again',
    static function (): bool {
        $vehicle = new CourtesyVehicle('CV-01');
        $vehicle->allocateTo('JC-1001');
        $vehicle->returnToFleet();
        return $vehicle->isAvailable() === true;
    }
);

check(
    'After returnToFleet(), it is allocated to nothing',
    static function (): bool {
        $vehicle = new CourtesyVehicle('CV-01');
        $vehicle->allocateTo('JC-1001');
        $vehicle->returnToFleet();
        return $vehicle->allocatedToJobCard() === null;
    }
);

check(
    'RULE: returning a vehicle that is not out is refused with DomainException',
    static fn(): bool => throws(
        DomainException::class,
        static fn() => (new CourtesyVehicle('CV-01'))->returnToFleet()
    )
);

check(
    'A returned vehicle can be allocated again',
    static function (): bool {
        $vehicle = new CourtesyVehicle('CV-01');
        $vehicle->allocateTo('JC-1001');
        $vehicle->returnToFleet();
        $vehicle->allocateTo('JC-2002');
        return $vehicle->allocatedToJobCard() === 'JC-2002';
    }
);


// ── No way past the rules ───────────────────────────────────────────────────

check(
    'No public property can be assigned from outside the class',
    static function (): bool {
        $reflection = new ReflectionClass(CourtesyVehicle::class);

        foreach ($reflection->getProperties() as $property) {
            if (!$property->isPublic() || $property->isStatic()) {
                continue;
            }

            $vehicle = new CourtesyVehicle('CV-PROBE');
            $name    = $property->getName();

            if (!$property->isInitialized($vehicle)) {
                continue;
            }

            // Assign the value it already holds. Harmless if permitted — it is
            // the permission we are testing, not the value.
            try {
                $vehicle->$name = $property->getValue($vehicle);
            } catch (Throwable) {
                continue;   // good: the language refused the write
            }

            return false;   // a writable public property is a hole in the model
        }

        return true;
    }
);

check(
    'There is no public method whose name begins with "set"',
    static function (): bool {
        $reflection = new ReflectionClass(CourtesyVehicle::class);

        foreach ($reflection->getMethods(ReflectionMethod::IS_PUBLIC) as $method) {
            if (str_starts_with(strtolower($method->getName()), 'set')) {
                return false;
            }
        }

        return true;
    }
);

check(
    'The domain class imports nothing outside the Workshop namespace',
    static function (): bool {
        $file = (new ReflectionClass(CourtesyVehicle::class))->getFileName();
        if ($file === false) {
            return false;
        }

        $source = (string) file_get_contents($file);

        // Top-level `use` statements only: anchored at column 0, so trait
        // imports inside a class body (which are indented) are not matched, and
        // neither is `function () use ($x)`.
        preg_match_all(
            '/^use\s+(?:function\s+|const\s+)?([A-Za-z_\\\\][A-Za-z0-9_\\\\]*)/m',
            $source,
            $matches
        );

        foreach ($matches[1] as $imported) {
            $imported = ltrim($imported, '\\');

            // Global built-ins are not a framework dependency.
            if (!str_contains($imported, '\\')) {
                continue;
            }
            if (str_starts_with($imported, 'Workshop\\')) {
                continue;
            }

            return false;
        }

        return true;
    }
);


acceptance_report();
